<div class="page-intro"><div><h2>Student documents</h2><p class="muted mb-0 mt-1">Securely upload and manage student files in Amazon S3.</p></div></div>
<div class="panel mb-4"><div class="panel-title">Upload a document</div><?php if(!$students): ?><div class="alert alert-warning mb-0">Add a student record first to upload documents.</div><?php else: ?><form method="post" action="upload_document.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-5"><label class="form-label">Select student *</label><select class="form-select" name="student_id" required><option value="">Choose student</option><?php foreach($students as $s): ?><option value="<?=(int)$s['id']?>"><?=e($s['student_code'].' · '.$s['full_name'])?></option><?php endforeach; ?></select></div><div class="col-md-7"><label class="form-label">Choose file * (PDF, image, DOC/DOCX; max 10 MB)</label><input class="form-control" type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"></div></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-primary px-4">Upload to S3</button></div></form><?php endif; ?></div>
